import {stability,adjacentChanges,treatmentEvents} from './sid-longitudinal-model.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=d=>new Date(d+'T12:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}),n=v=>v.toFixed(3),sign=v=>(v>0?'+':'')+n(v);
let state;
export function initLongitudinal(callbacks){$('overlayKind').onchange=()=>draw();$('stableFloor').oninput=()=>drawStability();$('stableRange').onchange=()=>drawStability();$('adjacentIntervals').onclick=e=>{const b=e.target.closest('[data-interval]');if(b)callbacks.interval(+b.dataset.interval)};$('stableRows').onclick=e=>{const b=e.target.closest('[data-stable]');if(b)callbacks.feature(b.dataset.stable)};}
export function updateLongitudinal(next){state=next;draw();drawStability();}
function draw(){if(!state)return;const {data,clinical,features,selected:r,start,end}=state;const samples=data.samples;const segments=adjacentChanges(features,samples);const largest=segments.reduce((a,b)=>a.brayCurtis>=b.brayCurtis?a:b);$('communitySummary').textContent=`Largest observed community shift: ${short(samples[largest.start].date)} → ${short(samples[largest.end].date)} (${(largest.brayCurtis*100).toFixed(1)}% Bray–Curtis dissimilarity). All features at this taxonomic level are included; filtering does not alter this distance.`;
$('adjacentIntervals').innerHTML=segments.map(s=>`<button class="interval-card ${start===s.start&&end===s.end?'active':''}" data-interval="${s.start}"><b>${short(samples[s.start].date)} → ${short(samples[s.end].date)}</b><span>${s.days} days between reported dates</span><strong>${(s.brayCurtis*100).toFixed(1)}% community dissimilarity</strong><span>${r?esc(r.name)+': '+sign((r.values[s.end]-r.values[s.start])*100)+' pp':'Select a taxon for its delta'}</span></button>`).join('');
if(!r){$('largestTaxonChange').textContent='';$('overlayNote').textContent='';$('trajectory').innerHTML='';$('exposureEvidence').innerHTML='Select a feature to explore exposure context.';return}
const kind=$('overlayKind').value,events=kind==='none'?[]:treatmentEvents(clinical.events,samples[0].date,samples.at(-1).date,kind),names=[...new Set(events.map(e=>e.title))];
const colors=['#b06b3e','#6b73a5','#a58c44','#528c91','#966277'];const color=e=>colors[names.indexOf(e.title)%colors.length];const l=180,right=720,top=30,bottom=230,base=295,height=base+names.length*26+18;const t0=Date.parse(samples[0].date),t1=Date.parse(samples.at(-1).date),x=d=>l+Math.max(0,Math.min(1,(Date.parse(d)-t0)/(t1-t0)))*(right-l),max=Math.max(...r.values)*1.15||.01,y=v=>bottom-v/max*(bottom-top);
let svg=`<svg viewBox="0 0 760 ${height}" role="img" aria-label="${esc(r.name)} share with treatment dates and periods on the same time axis"><text x="${l}" y="16" font-size="12" fill="#526d66">Share of reported abundance (%)</text><rect x="${x(samples[start].date)}" y="${top}" width="${x(samples[end].date)-x(samples[start].date)}" height="${bottom-top}" fill="#166f60" opacity=".045"/>`;
for(let i=0;i<4;i++){const yy=bottom-(bottom-top)*i/3;svg+=`<line x1="${l}" x2="${right}" y1="${yy}" y2="${yy}" stroke="#dce3db"/><text x="${l-9}" y="${yy+4}" text-anchor="end" font-size="11">${(max*100*i/3).toFixed(2)}</text>`}
for(const e of events){const xx=x(e.date),xx2=x(e.end_date||e.date),c=color(e),title=esc(`${e.title}: ${e.date}${e.end_date?' to '+e.end_date:''}${e.dose?' · '+e.dose:''}`);svg+=e.end_date?`<rect x="${xx}" y="${top}" width="${Math.max(1,xx2-xx)}" height="${bottom-top}" fill="${c}" opacity=".025"><title>${title}</title></rect>`:`<line x1="${xx}" x2="${xx}" y1="${top}" y2="${bottom}" stroke="${c}" opacity=".4" stroke-dasharray="2 4"><title>${title}</title></line>`;const yy=base+names.indexOf(e.title)*26;svg+=e.end_date?`<line x1="${xx}" x2="${xx2}" y1="${yy}" y2="${yy}" stroke="${c}" stroke-width="7"><title>${title}. Source-reported period; dosing frequency unverified.</title></line>`:`<circle cx="${xx}" cy="${yy}" r="4" fill="${c}"><title>${title}</title></circle>`;}
names.forEach((name,i)=>{svg+=`<text x="${l-10}" y="${base+i*26+4}" text-anchor="end" font-size="10" fill="${colors[i%colors.length]}"><title>${esc(name)}</title>${esc(name.length>27?name.slice(0,25)+'…':name)}</text>`});
svg+=`<polyline points="${r.values.map((v,i)=>x(samples[i].date)+','+y(v)).join(' ')}" fill="none" stroke="#166f60" stroke-width="2.5"/>`;
r.values.forEach((v,i)=>{const xx=x(samples[i].date),s=samples[i];if(i>1)svg+=`<line x1="${xx}" x2="${xx}" y1="${top}" y2="${bottom}" stroke="#856244" stroke-dasharray="5 5" opacity=".5"/>`;svg+=`<circle cx="${xx}" cy="${y(v)}" r="${i===start||i===end?6:4}" fill="#166f60" stroke="white" stroke-width="2"><title>${s.date}: ${n(v*100)}%. ${esc(s.dateNote)}</title></circle><text x="${xx}" y="${i===3?269:250}" text-anchor="middle" font-size="11">${short(s.date)}${i===2?' *':i>2?' †':''}</text>`});$('trajectory').innerHTML=svg+'</svg>';
$('overlayNote').textContent=kind==='none'?'Treatment overlay hidden. Evidence below still uses documented exposures within the selected comparison interval.':'Bars = reported treatment periods; dots / vertical dotted lines = dated entries. Shading shows exposure timing, not an effect size. Periods are clipped to the plot; hover marks for full dates. Repeated identical entries across timelines are shown once.';
const byTaxon=segments.map(s=>({...s,delta:(r.values[s.end]-r.values[s.start])*100})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));$('largestTaxonChange').textContent=`${r.name}’s largest observed adjacent-visit change: ${short(samples[byTaxon[0].start].date)} → ${short(samples[byTaxon[0].end].date)}, ${sign(byTaxon[0].delta)} pp. The change could have occurred anywhere between these samples.`;
renderExposureEvidence(r,treatmentEvents(clinical.events,samples[start].date,samples[end].date),samples[start].date,samples[end].date);
}
function renderExposureEvidence(r,events,start,end){const names=[...new Set(events.map(e=>e.title))];let html=`<p class="small">Matched to documented treatment entries overlapping ${esc(start)} → ${esc(end)} (no padding). Papers are curated research context; no treatment effect on ${esc(r.name)} is established.</p>`;
const card=(title,body,limit,url)=>`<article class="evidence-card"><h4>${title}</h4><p>${body}</p><p class="caution">${limit}</p><a href="${url}" target="_blank" rel="noopener">Read primary study ↗</a></article>`;
if(events.some(e=>e.subcategory==='Antibiotics'))html+=card('Antibiotics · broader class context','Dethlefsen & Relman followed three people through two ciprofloxacin courses. Community responses and recovery varied between individuals. This supports examining perturbation and persistence together.','Different antibiotic and study population: this does not predict the effects of Sid’s dalbavancin or cefazolin, or a direction for this taxon.','https://pmc.ncbi.nlm.nih.gov/articles/PMC3063582/');
if(names.includes('Metformin')){html+=card('Metformin · same drug, different population','Wu et al. (2017) randomized treatment-naive type 2 diabetes participants to metformin or placebo for four months and observed changes in the gut microbiome.','Drug-level evidence only. This is not a demonstrated explanation for the selected taxon or Sid’s trajectory; overlapping treatments and sparse sampling prevent attribution.','https://www.nature.com/articles/nm.4345');if(r.genus==='Bacteroides')html+=card('Metformin × Bacteroides · species-specific research','Sun et al. (2018) reported lower B. fragilis after three days of metformin in people with newly diagnosed type 2 diabetes, with mechanistic follow-up in mice.',r.species==='Bacteroides fragilis'?'Species name matches, but strain, population and experimental context differ. Directional agreement would not establish causation.':'The study concerns B. fragilis. A genus-level Bacteroides change or another species cannot be treated as that result.','https://pubmed.ncbi.nlm.nih.gov/30397356/');}
if(names.includes('Dostarlimab'))html+=card('Checkpoint therapy · response associations','Lee et al. (2022) found cohort-dependent microbiome associations with checkpoint-inhibitor response in melanoma.','This is not evidence that dostarlimab causes this taxon to rise or fall, and melanoma response associations do not establish osteosarcoma treatment benefit.','https://pmc.ncbi.nlm.nih.gov/articles/PMC8938272/');
html+=`<details><summary>Search taxon + exposure literature (${names.length} treatments)</summary><p class="small">Candidate searches, not reviewed results. No curated drug-specific card is available here for ${esc(names.filter(n=>!['Metformin','Dostarlimab'].includes(n)).join(', ')||'additional exposures' )}. Antibiotic cards above are class context.</p>${names.map(name=>{const q=`TITLE_ABS:"${r.resolved?r.name:'gut microbiome'}" AND TITLE_ABS:"${name.replaceAll('"','')}"`;return `<a class="exposure-search" href="https://europepmc.org/search?query=${encodeURIComponent(q)}" target="_blank" rel="noopener">${esc(r.resolved?r.name:'Gut microbiome')} + ${esc(name)} ↗</a>`}).join('')}</details>`;$('exposureEvidence').innerHTML=html;}
function drawStability(){if(!state)return;const floor=Math.max(0,+$('stableFloor').value||0),all=stability(state.features,floor),limit=$('stableRange').value,shown=all.filter(f=>limit==='all'||f.relativeRange<=+limit);$('stabilitySummary').textContent=`${all.length} named ${state.level==='family'?'family groups':state.level==='genus'?'genus groups':'SGBs'} meet the presence threshold in all 5 visits; ${shown.length} meet the selected variability ceiling. All five visits are used, independent of comparison, search and delta filters.`;$('stableRows').innerHTML=shown.map(f=>`<tr><td><button data-stable="${esc(f.id)}">${esc(f.name)}</button></td><td>${n(f.median*100)}</td><td>${n(f.min*100)}–${n(f.max*100)}</td><td>${n(f.rangePP)}</td><td>${f.relativeRange.toFixed(1)}%</td></tr>`).join('')||'<tr><td colspan="5">No named features meet this definition. That is an informative result; try a broader variability ceiling.</td></tr>';}
